repo.parcels.py:
"""Parcel records."""


class Parcel:
    def __init__(self, depot, grams):
        self.depot = depot
        self.grams = grams

    def __repr__(self):
        return "Parcel(%r, %r)" % (self.depot, self.grams)


ROWS = [('york', 26), ('leeds', 24), ('bath', 45), ('hull', 3), ('york', 44)]


def load_parcels():
    """Yield the stored parcels one at a time."""
    for depot, grams in ROWS:
        yield Parcel(depot, grams)

repo.podium.py:
"""Top parcels by grams."""


def _take_largest(parcels):
    """Remove and return the parcel with the largest grams."""
    best = max(parcels, key=lambda x: x.grams)
    parcels.remove(best)
    return best


def podium(parcels, places=3):
    """Return the top `places` parcels by grams, largest first. The caller's list is left as it was."""
    top = []
    while parcels and len(top) < places:
        top.append(_take_largest(parcels))
    return top


def report(parcels):
    """Return the podium values, the number of parcels and every grams."""
    return {"podium": [x.grams for x in podium(parcels)], "count": len(parcels), "all": [x.grams for x in parcels]}


def group_by_depot(parcels):
    """Return a dict from depot to the list of parcels with that depot."""
    groups = {}
    for x in parcels:
        groups.setdefault(x.depot, []).append(x)
    return groups


def largest_grams(parcels):
    """Return the largest grams, or None when there are no parcels."""
    values = [x.grams for x in parcels]
    return max(values) if values else None

