from parcels import load_parcels, ROWS
from podium import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_parcels()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_parcels()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_parcels()))
    assert [x.grams for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_parcels())
    podium(data, 2)
    assert [x.grams for x in data] == VALUES


def test_one_place():
    assert [x.grams for x in podium(list(load_parcels()), 1)] == [max(VALUES)]
